try{
    if (window.location.href.lastIndexOf('/debug') >= 0) {
        $('body').append('<div id="log"></div>');

        console.olog =  console.log;
        console.log = function (msg, param1, param2, param3, param4, param5, param6, param7, param8, param9) {
            try {
                var str = "";
                var args = Array.prototype.slice.call(arguments);
                args.forEach(function(item){
                    str = "<li>" + JSON.stringify(item) + "</li>";
                });
                console.olog(msg, param1, param2, param3, param4, param5, param6, param7, param8, param9);  //maintains existing logging via the console.
                $("#log").append("<div style=\"border-style: solid; border-width:2px\"><ul>" + str + "</ul></div>");
            } catch (e) { }
        }

        window.onerror = function (message, url, linenumber) {
            try{
                console.log("JavaScript error: " + message + " on line " +
                        linenumber + " for " + url + "\n\n");
            } catch (e) { }
        }
    }
}
