define('shared/services/common',[],function () {

    var common = {
            formatQuarter: formatQuarter,
            formatQuarters: formatQuarters,
            formatCutOffDate: formatCutOffDate,
            formatDueDate: formatDueDate,
            checkTfn: checkTfn,
            checkAbn: checkAbn,
            thousandSeperator: thousandSeperator,
            currencyFormatter: currencyFormatter,
            percentageFormatter: percentageFormatter,
            labelScroll: labelScroll,
            currentFinYear: currentFinYear,
            formatFinYear: formatFinYear,
            cancelNavWhenModalActive: cancelNavWhenModalActive,
            dateFormats: ["D/MM/YYYY", "DD/MM/YYYY"],
            formatYesNo: formatYesNo,
            requirePromise: requirePromise//,
            //createBigNumber: createBigNumber
        };

        return common;

        function cancelNavWhenModalActive(item, close, settings) {
            // Select any elements that are currently active bootstrap modals using the classes .modal .fade .in
            var hms = $(".modal.fade.in");
            if (hms && hms.length > 0) {
                // If there are any active bootstrap modals, hide them and then return false to cancel the navigation.
                hms.modal('hide');
                return false;
            };

            return true;
        }


        function formatQuarter(quarter) {
            var parts = quarter.split("-");

            switch (parts[1]) {
                case "1":
                    return "1 January " + parts[0] + " to 31 March " + parts[0];
                    break;
                case "2":
                    return "1 April " + parts[0] + " to 30 June " + parts[0];
                    break;
                case "3":
                    return "1 July " + parts[0] + " to 30 September " + parts[0];
                    break;
                case "4":
                    return "1 October " + parts[0] + " to 31 December " + parts[0];
                    break
                default:
                    throw "quarter needs to be 1-4";
            }
        }

        function formatCutOffDate(quarter) {
            var parts = quarter.split("-");

            switch (parts[1]) {
                case "1":
                    return "28 April " + parts[0];
                    break;
                case "2":
                    return "28 July " + parts[0];
                    break;
                case "3":
                    return "28 October " + parts[0];
                    break;
                case "4":
                    return "28 January " + parts[0];
                    break;
                default:
                    throw "quarter needs to be 1-4";
            }
        }

        function formatDueDate(quarter) {
            var parts = quarter.split("-");

            switch (parts[1]) {
                case "1":
                    return "28 May " + parts[0];
                    break;
                case "2":
                    return "28 August " + parts[0];
                    break;
                case "3":
                    return "28 November " + parts[0];
                    break;
                case "4":
                    return "28 February " + parts[0];
                    break
                default:
                    throw "quarter needs to be 1-4";
            }
        }

        function formatQuarters(quarters) {
            var formatedItems = [];

            for (var i = 0; i < quarters().length; i++) {
                formatedItems.push(formatQuarter(quarters[i]));
            }

            return formatedItems;
        }

        function checkTfn(tfn) {
            $.get("/Services/Validation/Tfn/" + tfn,
                function (data) { return !data; });
        }

        function checkAbn(abn) {
            $.get("/Services/Validation/Abn/" + abn,
                function (data) { return data; });
        }

        //only works on integers
        function thousandSeperator(number) {
            return number.replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
        }

    //currency formatter
        function currencyFormatter(number) {
            if (typeof number === 'undefined' || number == null || number == '') {
                number = '0';
            }
            if (number < 0) {
                return "-$" + (parseInt(number) * -1).toString().replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
            }
            else {
                return "$" + number.replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
            }
        }

        function percentageFormatter(number, places, round) {
            if (number == '' || typeof number == null || typeof number == 'undefined') {
                number = 0;
            }

            var config = {};
            if(typeof places == 'undefined'){
                config.DECIMAL_PLACES = 2;
            } else {
                config.DECIMAL_PLACES = places;
            }
            if(typeof round !== 'undefined'){
                config.ROUNDING_MODE = round;
            }
            BigNumber.config(config);
            var returnVal = new BigNumber(number).times(100).toString();
            return returnVal + '%';
        }

        function labelScroll(labelId) {
            $(document).scrollTop($(labelId).offset().top);
            $(labelId).focus();
        };

        //returns financial year according to system date and optional format (default single year)
        function currentFinYear(format) {
            var today = moment();   
            var returnVal;
            if (today.month() < 6) {
                if (format == "yyyy" || typeof format === 'undefined') {
                    returnVal = Number(today.year());
                } else if (format == "yyyy - yyyy") {
                    returnVal = (Number(today.year()) - 1) + "-" + today.format("YYYY");
                } else if (format == "yyyy - yy") {
                    returnVal = (Number(today.year()) - 1) + "-" + today.format("YY");
                }
            } else {
                if (format == "yyyy" || typeof format === 'undefined') {
                    return Number(today.year()) + 1;
                } else if (format == "yyyy - yyyy") {
                    return today.year() + "-" + (Number(today.format("YYYY")) + 1);
                } else if (format == "yyyy - yy") {
                    return today.year() + "-" + (Number(today.format("YY")) + 1);
                }
            }
            return returnVal;
        }

        
   
        function formatFinYear(year, format) {
            var input = moment(year.toString() + "-06-30");
            
            if (typeof format == "undefined" || format == "yyyy - yy") {
                return (input.year() - 1) + "-" + input.format("YY");
            }

            if (format == "yyyy - yyyy") {
                return (input.year() - 1) + "-" + input.year();
            }
        }

        function formatYesNo(str) {
            str = str.toUpperCase()
            if (str == "YES") {
                return 'Yes';
            } else if (str == "NO") {
                return 'No';
            } else {
                return '';
            }
        }

        //returns promise, resolve with require'd path value
        function requirePromise(requirePath) {
            var dfd = Q.defer();
            require([requirePath], function (val) {
                dfd.resolve(val);
            });
            return dfd.promise;
        };

        //function createBigNumber(str) {
        //    try {
        //        return str == '' ? new BigNumber(0) : new BigNumber(str);
        //    } catch (e) {
        //        console.log('createBigNumber - error :' + e.message);
        //        return;
        //    }
        //}
});


