define("legalDatabase.web.min", function(){});
 
define('shared/services/common',[],function () {

    var common = {
            formatQuarter: formatQuarter,
            formatQuarters: formatQuarters,
            formatCutOffDate: formatCutOffDate,
            formatDueDate: formatDueDate,
            checkTfn: checkTfn,
            checkAbn: checkAbn,
            thousandSeperator: thousandSeperator,
            currencyFormatter: currencyFormatter,
            percentageFormatter: percentageFormatter,
            labelScroll: labelScroll,
            currentFinYear: currentFinYear,
            formatFinYear: formatFinYear,
            cancelNavWhenModalActive: cancelNavWhenModalActive,
            dateFormats: ["D/MM/YYYY", "DD/MM/YYYY"],
            formatYesNo: formatYesNo,
            requirePromise: requirePromise//,
            //createBigNumber: createBigNumber
        };

        return common;

        function cancelNavWhenModalActive(item, close, settings) {
            // Select any elements that are currently active bootstrap modals using the classes .modal .fade .in
            var hms = $(".modal.fade.in");
            if (hms && hms.length > 0) {
                // If there are any active bootstrap modals, hide them and then return false to cancel the navigation.
                hms.modal('hide');
                return false;
            };

            return true;
        }


        function formatQuarter(quarter) {
            var parts = quarter.split("-");

            switch (parts[1]) {
                case "1":
                    return "1 January " + parts[0] + " to 31 March " + parts[0];
                    break;
                case "2":
                    return "1 April " + parts[0] + " to 30 June " + parts[0];
                    break;
                case "3":
                    return "1 July " + parts[0] + " to 30 September " + parts[0];
                    break;
                case "4":
                    return "1 October " + parts[0] + " to 31 December " + parts[0];
                    break
                default:
                    throw "quarter needs to be 1-4";
            }
        }

        function formatCutOffDate(quarter) {
            var parts = quarter.split("-");

            switch (parts[1]) {
                case "1":
                    return "28 April " + parts[0];
                    break;
                case "2":
                    return "28 July " + parts[0];
                    break;
                case "3":
                    return "28 October " + parts[0];
                    break;
                case "4":
                    return "28 January " + parts[0];
                    break;
                default:
                    throw "quarter needs to be 1-4";
            }
        }

        function formatDueDate(quarter) {
            var parts = quarter.split("-");

            switch (parts[1]) {
                case "1":
                    return "28 May " + parts[0];
                    break;
                case "2":
                    return "28 August " + parts[0];
                    break;
                case "3":
                    return "28 November " + parts[0];
                    break;
                case "4":
                    return "28 February " + parts[0];
                    break
                default:
                    throw "quarter needs to be 1-4";
            }
        }

        function formatQuarters(quarters) {
            var formatedItems = [];

            for (var i = 0; i < quarters().length; i++) {
                formatedItems.push(formatQuarter(quarters[i]));
            }

            return formatedItems;
        }

        function checkTfn(tfn) {
            $.get("/Services/Validation/Tfn/" + tfn,
                function (data) { return !data; });
        }

        function checkAbn(abn) {
            $.get("/Services/Validation/Abn/" + abn,
                function (data) { return data; });
        }

        //only works on integers
        function thousandSeperator(number) {
            return number.replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
        }

    //currency formatter
        function currencyFormatter(number) {
            if (typeof number === 'undefined' || number == null || number == '') {
                number = '0';
            }
            if (number < 0) {
                return "-$" + (parseInt(number) * -1).toString().replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
            }
            else {
                return "$" + number.replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
            }
        }

        function percentageFormatter(number, places, round) {
            if (number == '' || typeof number == null || typeof number == 'undefined') {
                number = 0;
            }

            var config = {};
            if(typeof places == 'undefined'){
                config.DECIMAL_PLACES = 2;
            } else {
                config.DECIMAL_PLACES = places;
            }
            if(typeof round !== 'undefined'){
                config.ROUNDING_MODE = round;
            }
            BigNumber.config(config);
            var returnVal = new BigNumber(number).times(100).toString();
            return returnVal + '%';
        }

        function labelScroll(labelId) {
            $(document).scrollTop($(labelId).offset().top);
            $(labelId).focus();
        };

        //returns financial year according to system date and optional format (default single year)
        function currentFinYear(format) {
            var today = moment();   
            var returnVal;
            if (today.month() < 6) {
                if (format == "yyyy" || typeof format === 'undefined') {
                    returnVal = Number(today.year());
                } else if (format == "yyyy - yyyy") {
                    returnVal = (Number(today.year()) - 1) + "-" + today.format("YYYY");
                } else if (format == "yyyy - yy") {
                    returnVal = (Number(today.year()) - 1) + "-" + today.format("YY");
                }
            } else {
                if (format == "yyyy" || typeof format === 'undefined') {
                    return Number(today.year()) + 1;
                } else if (format == "yyyy - yyyy") {
                    return today.year() + "-" + (Number(today.format("YYYY")) + 1);
                } else if (format == "yyyy - yy") {
                    return today.year() + "-" + (Number(today.format("YY")) + 1);
                }
            }
            return returnVal;
        }

        
   
        function formatFinYear(year, format) {
            var input = moment(year.toString() + "-06-30");
            
            if (typeof format == "undefined" || format == "yyyy - yy") {
                return (input.year() - 1) + "-" + input.format("YY");
            }

            if (format == "yyyy - yyyy") {
                return (input.year() - 1) + "-" + input.year();
            }
        }

        function formatYesNo(str) {
            str = str.toUpperCase()
            if (str == "YES") {
                return 'Yes';
            } else if (str == "NO") {
                return 'No';
            } else {
                return '';
            }
        }

        //returns promise, resolve with require'd path value
        function requirePromise(requirePath) {
            var dfd = Q.defer();
            require([requirePath], function (val) {
                dfd.resolve(val);
            });
            return dfd.promise;
        };

        //function createBigNumber(str) {
        //    try {
        //        return str == '' ? new BigNumber(0) : new BigNumber(str);
        //    } catch (e) {
        //        console.log('createBigNumber - error :' + e.message);
        //        return;
        //    }
        //}
});


define('shared/services/baseViewModel',['require', './common'], function (require, common) {

    var baseViewModel = {
        canDeactivate: canDeactivate
        };

    return baseViewModel;

    function canDeactivate(item, close, settings) {
        var retVal = common.cancelNavWhenModalActive(item, close, settings);

        return retVal;
    }


});



// childAreaViewStrategy is a require module that provides a custom view loacator strategy for use in durandal composition.
// It is used to override the defaultStrategy used by the viewLocator to map a moduleId to a viewId
// To use it in a compose or router databinding, simply use strategy:'<childapp>/services/childAreaViewStrategy'
// This strategy supports freeform and folder seperated vm + v approaches to module organisation.
// Where an area is provided, the naming standard that applies is <module folder>/<area>/<viewName>.html
// Where no area is provided, the naming standard that applies is <module folder>/<viewName>.html
define('shared/services/childAreaViewStrategy',['durandal/system', 'durandal/viewLocator'], function (system, viewLocator) {
    return function (settings) {
        // As module is already an object, use system.getModuleId to extract the moduleId string from the module
        var moduleId = system.getModuleId(settings.model);

        // Use the value after the last '/' as the viewName
        var viewName = moduleId.substring(moduleId.lastIndexOf('/') + 1, moduleId.length);

        // Declare the path variable
        // If area is provided, inject it in between the module folder and the viewName, otherwise, just reconstruct the path to find the default viewName
        var path;
        if (settings.area && settings.area != '') {
            var path = moduleId.substring(0, moduleId.lastIndexOf('/') + 1) + settings.area + '/' + viewName + '.html';
        }
        else {
            var path = moduleId.substring(0, moduleId.lastIndexOf('/') + 1) + viewName + '.html';
        }

        // Mimic the viewLocator.locateViewForObject call
        // Call locateView passing in the constrcued path, null for the area, and the parent element
        // The area is set to null to prevent locateView from attempting to use the area to contruct the path again.
        // settings.parent is passed to allow locateView to see if the view already exists in the composition context, allowing reuse and rebinding.

        // Returns the DOM fragment contained in the located view.
        return viewLocator.locateView(path, null, settings.parent);
    };
});
/******************************************************************************
 * defaultDataRetention.js
 * Author: Nick Fun
 * Description: Provides standard data retention for applications - 
 * Clear stack from a node (node a) onwards if the next node(node b) from that node (node a) has changed (to node c).
 * 
 *
 * 23/04/2014 - First version with comments :)
 *****************************************************************************/
define('shared/services/defaultDataRetention',[], function () {

    return function dataRetention(navRoutes, node, previousDestinationValue, destinationValue, childObjects) {
		//declare locally whatever objects from child app you need here
		var datacontext = childObjects.datacontext;
		var nodeExists = $.grep(navRoutes, function (e) { return e.node == node; });
	    var nodeIndex = $.inArray(nodeExists[0], navRoutes);
        //reset question responses if next screen is not the same
	    if (nodeExists.length > 0) {
	        if (previousDestinationValue != destinationValue) {
	            var questionGroup = datacontext.getQuestionGroupByKey(navRoutes[nodeIndex].node);
	            datacontext.resetSubsequentQuestions(questionGroup.ordinal());
	        }
	    }
	    return navRoutes;
	};
});
define('shared/services/jqmUtil',[],function () {

    return {

        triggerCreate: function (html) {
            $(html).trigger('create');
        }
    };

});

/******************************************************************************
 * loader.js
 * Author: Ben Gillard, Nick Fun
 * Description: Provides navigation functionality between nodes as defined by applications ruleEngine.js. 
 * It makes calls to data retention functions to deal with data retention.
 *
 * 2013 - 02/2014 - Initial version
 * 22/04/2014 - First version with comments :)
 *****************************************************************************/
define('shared/services/loader',[], function () {


    var loader = {
        setAppConfig: setAppConfig,
        appConfig: null,
        loadCalculatorItems: loadCalculatorItems,
        loadRoutes: loadRoutes,
        loadNavRules: loadNavRules
    };

    return loader;

    function setAppConfig(appConfig) {
        this.appConfig = appConfig;
    }
    
    function loadCalculatorItems(datacontext) {

        var loadedQuestionGroups = loadQuestionGroups(datacontext, this.appConfig.questiongroups);
        loadQuestions(datacontext, this.appConfig.questions, loadedQuestionGroups);
            
    };
 

    function loadRoutes() {
  

        var loadedRoute = [];     
        var firstNavRoute = false;
        for (var i = 0; i < this.appConfig.questiongroups.length; i++) {

            var theRoute = this.appConfig.questiongroups[i].key;
            //only set first navigatable route 
            if (firstNavRoute == false && this.appConfig.questiongroups[i].nav == true) {
                theRoute = ['', this.appConfig.questiongroups[i].key];
                firstNavRoute = true;
            }

            var obj = {
                route: theRoute,
                moduleId: this.appConfig.questiongroups[i].key,
                title: this.appConfig.questiongroups[i].headingtext,
                nav: true
            };

            if (this.appConfig.questiongroups[i].nav == true) {
                loadedRoute.push(obj);
            }

        }

        return loadedRoute

    };


    function loadNavRules() {

    };

    
    function loadQuestionGroups(datacontext, questiongroups) {
        
        //temp store for the Question Groups loaded into the datastore
        var loadedQGs = {};

        //throw error if no Question Groups configured
        if (questiongroups.length == 0)
            throw "Badly formed config. Must contain at least one QuestionGroups item.";

        //validate and load each Question Group
        for (var i = 0; i < questiongroups.length; i++) {

            //config error checking
            if (typeof (questiongroups[i].key) == "undefined")
                throw "Badly formed config QuestionGroups item. Item must contain key property.";

            if (typeof (questiongroups[i].ordinal) == "undefined")
                throw "Badly formed config QuestionGroups item (key: " + questiongroups[i].key() + "). Item must contain ordinal property.";

            if (typeof (questiongroups[i].headingtext) == "undefined")
                throw "Badly formed config QuestionGroups item (key: " + questiongroups[i].key() + "). Item must contain headingtext property.";

            //load the Question Group into the datastore

            loadedQGs[questiongroups[i].key] = datacontext.addQuestionGroup(questiongroups[i].key, questiongroups[i].ordinal, questiongroups[i].headingtext);


        }

        return loadedQGs;

    };


    function loadQuestions(datacontext, questions, loadedQuestionGroups) {
        
        //throw error if no Question Groups configured
        if (questions.length == 0)
            throw "Badly formed config. Must contain at least one Questions item.";

        //validate and load each Question 
        for (var i = 0; i < questions.length; i++) {

            //config error checking
            if (typeof (questions[i].key) == "undefined")
                throw "Badly formed config Questions item. Item must contain key property.";

            if (typeof (questions[i].ordinal) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). Item must contain ordinal property.";

            if (typeof (questions[i].defaultvalue) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). Item must contain defaultvalue property.";

            if (typeof (questions[i].type) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). Item must contain type property.";

            if (typeof (questions[i].refdatakey) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). Item must contain refdatakey property.";

            if (typeof (questions[i].text) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). Item must contain text property.";

            if (typeof (questions[i].explanatory) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). Item must contain explanatory property.";

            if (typeof (questions[i].questiongroup) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). Item must contain questiongroup property.";

            //try to find the Question Group for this Question
            var QG = loadedQuestionGroups[questions[i].questiongroup];

            if (typeof (QG) == "undefined")
                throw "Badly formed config Questions item (key: " + questions[i].key + "). The questiongroup property does no match a Question Group key in the config.";

            //load the Question into the datastore
            var q = datacontext.addQuestion(questions[i].key, questions[i].ordinal, questions[i].defaultvalue, questions[i].defaultvalue, questions[i].type, questions[i].refdatakey, questions[i].text, questions[i].explanatory, QG);

        }

    };


});
