define('services/jqmAdapter',['jquery', 'services/logger'],
    function ($, logger) {
        var routeProps = {
            "h": { "header": "headerhome", "footer": "footerhome" },
            "a": { "header": "headerapp", "footer": "" },
            "i": { "header": "headerindividuals", "footer": "footerhome" },
            "s": { "header": "headerapp", "footer": "footerhome" },
            "e": { "header": "headerreport", "footer": ""},
            "default": { "header": "headerapp", "footer": "" },
        };

        var vm = {
            triggerCreate: triggerCreate,
            appendContent: appendContent,
            setHeaderTitle: setHeaderTitle,
            setHostTheme: setHostTheme,
            setChildTheme: setChildTheme,
            headerName: ko.observable("headerapp"),
            footerName: ko.observable(""),
            childHeaderName: ko.observable(""),
            childFooterName: ko.observable(""),
            headerTitle: ko.observable("")
        };

        vm.triggerPageCreate = function (){
            var page = $("div:jqmData(role='page')");
            $(page).trigger('pagecreate');
        };

        vm.headerContent = ko.computed(function () {
            var targetElement = $("div[data-role='header']")
            if (!(targetElement && targetElement.length > 0)) {
                return
            };

            if (vm.childHeaderName && (vm.childHeaderName() != "")) {
                vm.appendContent(vm.childHeaderName(), 'header', targetElement, vm.setHeaderTitle, vm.headerTitle());
            } else {
                if (vm.headerName() == "") {
                    targetElement.empty();
                } else {
                    vm.appendContent(vm.headerName(), 'header', targetElement, vm.setHeaderTitle, vm.headerTitle());
                };
            };
        });

        vm.footerContent = ko.computed(function () {
            var targetElement = $("div[data-role='footer']")
            if (!(targetElement && targetElement.length > 0)) {
                return
            };

            if (vm.childFooterName && (vm.childFooterName() != "")) {
                vm.appendContent(vm.childFooterName(), 'footer', targetElement);
            } else {
                if (vm.footerName() == "") {
                    targetElement.empty();
                } else {
                    vm.appendContent(vm.footerName(), 'footer', targetElement);
                };
            }
        });

        return vm;

        function triggerThemeChange(theme) {
            //call changePageTheme to alter the JQM page
            $.mobile.changePageTheme(theme);
        };

        function closePanel() {
            //Close the panel if it exists.
            var panel = $(":jqmData(role='panel')");

            if (panel && panel.length > 0) {
                var paneldata = $.data(panel[0], "mobile-panel");

                if (paneldata && paneldata._open == true) {
                    panel.panel("close");
                }
            }
        };

        function setChildTheme(theme, title) {
            logger.log('jqmAdapter:setChildTheme method called', null, true);

            //Get JQuery wrapped reference to JQM page element
            var page = $("div:jqmData(role='page')");

            //Read currentTheme if required
            var currentTheme = page.attr("data-theme");

            // Set the headerTitle observable of the shell if the current route title is different.
            // Not necessary if change detection in the observable is smart enough.
            if (title != vm.headerTitle()) {
                vm.headerTitle(title);
            }

            if (currentTheme && theme && currentTheme != theme) {
                //Update route based observables for header and footer
                if (routeProps) {
                    vm.childHeaderName(routeProps[theme]["header"] || routeProps["default"]["header"] || "headerapp");
                    vm.childFooterName(routeProps[theme]["footer"] || routeProps["default"]["footer"] || "");
                }
                //$("#nav-panel").hide();
                triggerThemeChange(theme);
            }

            // Possibly move this to only happen if theme changes
            //trigger create function once as this will process all widgets in un-enhanced HTML using the currentTheme after possible modification by $.mobile.changeGlobalTheme
            $(page).trigger('pagecreate');
        };

        function setHostTheme(theme, title, instance, instruction, router) {
            logger.log('jqmAdapter:setHostTheme method called', null, true);

            //Get JQuery wrapped reference to JQM page element
            var page = $("div:jqmData(role='page')");

            //Read currentTheme if required
            var currentTheme = page.attr("data-theme");
            //Retrieve the routeTheme or default to 'a'
            //var routeTheme = theme;

            // Set the headerTitle observable of the shell if the current route title is different.
            // Not necessary if change detection in the observable is smart enough.
            //var routeTitle = title
            if (title != vm.headerTitle()) {
                vm.headerTitle(title);
            }

            if (currentTheme && theme && currentTheme != theme) {
                //Update route based observables for header and footer
                if (routeProps) {
                    // clear childHeader and Footer
                    vm.childHeaderName("");
                    vm.childFooterName("");
                    vm.headerName(routeProps[theme]["header"] || routeProps["default"]["header"] || "headerapp");
                    vm.footerName(routeProps[theme]["footer"] || routeProps["default"]["footer"] || "");
                }

                triggerThemeChange(theme);
            }


            //trigger create function once as this will process all widgets in un-enhanced HTML using the currentTheme after possible modification by $.mobile.changeGlobalTheme
            $(page).trigger('pagecreate');

            //Close panel if it exists and is open
            closePanel();

            // Used to display the header if we are moving away from the report
            if ($("#headerArea").css("display") && $("#headerArea").css("display") == "none") {
                $("#headerArea").show();
            }

            if ($("link[href$='jquery.mobile.ato-theme.min.css']") && $("link[href$='jquery.mobile.ato-theme.min.css']").prop("disabled")) {
                $("link[href$='jquery.mobile.ato-theme.min.css']").prop("disabled", false);
                $("link[href$='mobile-ato-content-styles.css']").remove();
                $("#headerArea").hide();
            }
        };

        function triggerCreate(html) {
            $(html).trigger('create');
        };

        function appendContent(fileName, datarole, $targetElement, templateCallBack, templateContent) {
            var filePath = 'text!views/mobile/' + fileName + '.html';
            console.log("shell.appendContent. filePath = {0}", filePath);
            require([filePath], function (fileContentString) {
                $targetElement.empty();
                var fileContentElements = $.parseHTML($.trim(fileContentString))

                if (templateCallBack && fileContentElements) {
                    templateCallBack(fileContentElements, templateContent);
                }                

                if (fileContentElements && fileContentElements.length > 0) {
                    if (fileContentElements.length == 1) {
                        if ($(fileContentElements[0]).attr("data-role") && $(fileContentElements[0]).attr("data-role") == datarole) {
                            $(fileContentElements[0]).children().appendTo($targetElement);
                        }
                        else {
                            $(fileContentElements).appendTo($targetElement);
                        }
                    } else {
                        $(fileContentElements).appendTo($targetElement);
                    }
                    // reapply trigger create to mark up jQuery Mobile Controls in the header or footer.
                    //triggerCreate($targetElement[0]);
                    //$targetElement.trigger("create");
                    //$targetElement.parent().trigger("create");
                    vm.triggerPageCreate();

                } else {
                    console.log("fileContentElement is null or empty.  fileContentString {0}", fileContentString);
                }
            })
        };

        function setHeaderTitle($content, headerTitle) {
            var targetElement = $($content[0]).find(".ui-title")

            if (targetElement.length > 0) {
                targetElement.text(headerTitle);
            }
        };
    }
);

