define('shared/widgets/sharedWidgets',['jquery', 'plugins/widget'], function ($, widget) {

    var sharedWidgets = function () {
        var self = this;
        self.defaultWidgetFolder = 'shared/widgets';
        self.registerWidgets = registerWidgets;
        self.registerWidget = registerWidget;
        self.registeredWidgets = [];
    };

    var thisWidgets = new sharedWidgets();
    return thisWidgets;


    //if you want to use default durandal mapping, pass a null rootArea and appModuleId as your widgetRootFolder
    function registerWidgets(kinds, rootArea, widgetRootFolder) {
        var self = this;
        var widgetRootFolder = (typeof widgetRootFolder === 'undefined' ? self.defaultWidgetFolder : widgetRootFolder);
        for (var i in kinds) {
            self.registerWidget(kinds[i], rootArea, widgetRootFolder);
        }
    }



    function registerWidget(widgetName, rootArea, widgetRootFolder) {
        var self = this;
        var viewId = rootArea != '' ? widgetRootFolder + '/' + widgetName + '/' + rootArea : widgetRootFolder + '/' + widgetName + '/web';
        var moduleId = rootArea != '' ? widgetRootFolder + '/' + widgetName + '/viewmodel' : widgetRootFolder + '/' + widgetName + '/viewmodel';
        if ($.inArray(widgetName, self.registeredWidgets) == -1) {
            self.registeredWidgets.push(widgetName);
            widget.registerKind(widgetName);
            widget.mapKind(widgetName, viewId, moduleId);
        } else {
            console.log('widget ' + widgetName + ' already exists');
            console.log('viewid :' + viewId);
            console.log('moduleId: ' + moduleId);
        }
    }

});
//Calc Host - shell module
define('viewmodels/shell',['durandal/app', 'durandal/system', 'plugins/router', 'services/logger', 'jquery', 'services/jqmAdapter', 'shared/widgets/sharedWidgets'],
    function (app, system, router, logger, $, uiAdapter, sharedWidgets) {
        var shell = {
            activate: activate,
            router: router,
            //navAttached: navAttached,
            attached: attached,
            compositionComplete: compositionComplete,
            getView: getView
        };

        return shell;

        //#region Internal Methods
        //Durandal lifecycle call back

        function activate() {
            return boot();
        }

        function attached() {
            if (hostConfig && hostConfig.hostArea == 'mobile') {
                //$.mobile.initializePage();
            }
        }

        function getView() {
            // router.applicationArea is not yet available in the lifecycle so we need to use the hostConfig directly.
            if (hostConfig && hostConfig.hostArea) {
                return 'views/' + hostConfig.hostArea + '/shell';
            } else {
                return 'views/shell';
            }
        }

        function compositionComplete(child, parent, settings) {
            console.log("composition Complete event");

            //default redirect to Legal Database
            if (router.activeItem() == null) {
                router.navigate('Law');
            }
        }

        function routerNavigationComplete(instance, instruction, router) {
            log('router:navigation:complete event handled', null, true);
            //set application title
            app.title = ko.unwrap(instruction.config.title);
        }

        //function navAttached(child, parent, settings) {
        //}

        function boot() {
            router.on('router:route:not-found', function (fragment) {
                logError('No Route Found', fragment, true);
            });

            router.on('router:navigation:complete', routerNavigationComplete);

            var routes = [
                { route: '', moduleId: 'home', title: 'Home', nav: 1 },
                { route: 'Law*details', moduleId: '../Law/shell', title: 'ATO Legal database', nav: true, hash: '#Law' }
            ];
            
            router.applicationArea = hostConfig.hostArea; 
            router.switchURL = hostConfig.switchURL;

            return router.makeRelative({ moduleId: 'viewmodels' }) // router will look here for viewmodels by convention
                .map(routes)            // Map the routes
                .buildNavigationModel() // Finds all nav routes and readies them
                .activate();            // Activate the router
        }

        function log(msg, data, showToast) {
            logger.log(msg, data, system.getModuleId(shell), showToast);
        }

        function logError(msg, data, showToast) {
            logger.logError(msg, data, system.getModuleId(shell), showToast);
        }
    });
/******************************************************************************
 * navigation.js
 * Author: Ben Gillard, Nick Fun
 * Description: Provides navigation functionality between nodes as defined by applications ruleEngine.js. 
 * It makes calls to data retention functions to deal with data retention.
 *
 * 2013 - 02/2014 - Initial version
 * 22/04/2014 - First version with comments :)
 *****************************************************************************/

// Includes file dependencies

define('shared/services/navigation',['jquery', 'viewmodels/shell'], function ($, hostShell) {
    // Shell,RuleEngine,DataContext,ChildRouter are all references to those particular functions for the current child application
    var shell;
    var ruleEngine;
    var datacontext;
    var childRouter;
    var appName = hostShell.router.activeInstruction().config.appModuleId;
    setNewNav('', '');

    //populated by appconfig in 'setNewNav'
    var useDefaultDataRetention;

    //variable that will be populated by a deferred object for loading data retention
    var dataRetentionIsLoaded;

    //navigation Routes
    var navRoutes = [];

    //active Route
    var activeRoute;

    var navigation = {
        navigate: navigate,
        navigateBack: navigateBack,
        getNavRoutes: getNavRoutes,
        getPreviousRoute: getPreviousRoute,
        getActiveRoute: getActiveRoute,        
        loadSavedNav: loadSavedNav,
        navigateRoute: navigateRoute
    };

    return navigation;

    function setNewNav(node, action) {
        appName = hostShell.router.activeInstruction().fragment.split('/')[0];
        var shellPath = hostShell.router.activeInstruction().config.moduleId;
        var ruleEnginePath = appName + '/services/ruleEngine';
        var dataContextPath = appName + '/data/datacontext';
        var appConfigPath = appName + '/appconfig';
        require([shellPath, ruleEnginePath, dataContextPath, appConfigPath], function (thisShell, thisRuleEngine, thisDatacontext, thisAppConfig) {
            //set the shell, ruleengine, childrouter, datacontext and app name to the 'new' child application
            shell = thisShell;
            ruleEngine = thisRuleEngine;
            childRouter = shell.router;
            datacontext = thisDatacontext;
            appName = shell.appModuleId;
            //if data retention is not set up in appconfig then it will default to use the standard data retention
            useDefaultDataRetention = typeof thisAppConfig.settings === 'undefined' ? true : thisAppConfig.settings[shell.router.area()].useDefaultDataRetention;
            dataRetentionIsLoaded = Q.defer();
            //determine data retention rules to require depending if using default or not
            var dataRetentionPath = useDefaultDataRetention ? 'shared/services/defaultDataRetention' : appName + '/services/dataRetention';
            require([dataRetentionPath], function (dataRetention) {
                //navigation.dataRetention = dataRetention;
                dataRetentionIsLoaded.resolve(dataRetention);
            });
            //required for when opening a new app into a screen that is not the first one
            if (node != '') {
                navigate(node, action);
            }
        });
    }

    //#region Internal Methods

    function navigate(node, action) {
        //if the child application has changed in the calchost rouster then it will set up the new ruleEngine, router etc. for navigation in the child app
        if (appName != hostShell.router.activeItem().appModuleId) {
            setNewNav(node, action);
        } else {
            var destination = ruleEngine.determineDestination(node, action);
            if (destination.type && destination.value) {
                //determine the destination value
                var destinationValue;
                if (destination.type === 'nav') {
                    destinationValue = this[destination.value]();
                } else if (destination.type === 'route') {
                    destinationValue = destination.value;
                }

                //set active route
                activeRoute = destinationValue;

                //retrieve previous destination value for data retention and set navigation routes;
                var newNode = $.grep(navRoutes, function (e) { return e.node == node; });
                var previousDestinationValue = newNode[0] ? newNode[0].nextNode : destinationValue;
                setNavRoutes(node, action, destinationValue);

                //dataRetention is loaded in 'setNewNav' function - getChildApplicationObjects passes child app datacontext, router, navroutes etc.
                Q.when(dataRetentionIsLoaded.promise).then(
                function (dataRetention) {
                    navRoutes = dataRetention(navRoutes, node, previousDestinationValue, destinationValue, getChildApplicationObjects());
                });

                //perform navigation
                if (destination.type === 'nav') {
                    return destinationValue;
                } else if (destination.type === 'route') {
                    //return router.navigate(destination.value);
                    // Need to use convertrouteToHash to enable full building of the appropriate hash for use in navigation
                    //destinationValue = destination.value;
                    return navigateRoute(destinationValue);
                } else {
                    // throw exception or log error
                }               
            }
            else {
                console.log("destination.type or destination.value is undefined");
            }
        }
    }

    //sets nav routes
    function setNavRoutes(node, action, destinationValue) {
        //modify nav routes collection
        if (action == 'restart') {
            //clear nav routes
            navRoutes = [];
        } else if (action == 'next') {
            //reset previous route attribute            
            $.each(navRoutes, function (key, value) {
                value.isPreviousNode = false;
            });
            //check if node exists
            var nodeExists = $.grep(navRoutes, function (e) { return e.node == node; });
            //if node doesn't exist, create a new nav route entry
            if (nodeExists.length == 0) {
                navRoutes.push({ node: node, nextNode: destinationValue, isPreviousNode: true });
            } else {
                //other wise set the existing nav route entry to the new destination value
                var nodeIndex = $.inArray(nodeExists[0], navRoutes);
                navRoutes[nodeIndex].nextNode = destinationValue;
                navRoutes[nodeIndex].isPreviousNode = true;
            }
        }
    };

    //load nav routes
    function loadSavedNav(savedNavRoutes,savedActiveRoute) {
        navRoutes = savedNavRoutes;
        activeRoute = savedActiveRoute;
    };

    //returns reference to child app objects
    function getChildApplicationObjects() {
        return { shell: shell, ruleEngine: ruleEngine, datacontext: datacontext, childRouter: childRouter }
    }

    function getPreviousRoute(screenKey) {
        try {
            var previousRoute = ko.utils.arrayFirst(navRoutes, function (route) {
                return route.nextNode == screenKey;
            });
            return previousRoute;
        }
        catch(e){
            console.log(e);
        };

    };

    function getNavRoutes() {
        var returnVal = navRoutes;
        return returnVal;
    };

    function getActiveRoute() {
        var returnVal = activeRoute;
        return returnVal;
    };


    function navigateBack(screenKey) {
        var screenKey = screenKey ? screenKey : activeRoute;
        var previousRoute = getPreviousRoute(screenKey);
        previousRoute = previousRoute ? previousRoute.node : activeRoute;
        //set new active route
        activeRoute = previousRoute;
        if (previousRoute) {
            navigateRoute(previousRoute);
        }
    }

    function navigateRoute(route){
        return shell.router.navigate(childRouter.convertRouteToHash(route));
    };

    //#endregion

});
