define('shared/services/refdataEngine',['komapping'], function (komapping) {

    var refdataEngine = {
        getRefData: getRefData,
        periodLookup: periodLookup,
        getRefDataFilePath: getRefDataFilePath,
        getExistingRequireRefData: getExistingRequireRefData
    };

    return refdataEngine;
    
    //Returns a promise object to let the caller know when the ref data is populated   
    //Looks at the breezeconfig for where to fetch the data from
    //
    //refDataType (mandatory) - the refdata type - if expecting from a JSON file, the file needs to be the same name as refDataType
    //obArray (non-mandatory) - a knockout observable array that the refdata items will be copied into 
    //appName (mandatory) - root folder of where you want to retrieve the data e.g. CGTDiscount or Shared'
    function getRefData(refDataType, obArray, appName) {
    
        var appconfigRequirePath = appName + '/appconfig';
        var appconfig = require(appconfigRequirePath);
        //design change - moved refData into rootFolder of a child application rootFolder/refData e.g. CGTDiscount/refData
        var filePath = getRefDataFilePath(refDataType, appName); //Need to lookup the app name from the child app shell appModuleId

        var config = appconfig.refdata;

        //deferred object to be returned to caller e.g. ref data providers
        var dfd = Q.defer();

        //try to get the refdata config section
        if (config.length > 0) {

            //try to get the config item with key that matches the refDataType
            var configitem = null;
            for (var i = 0; i < config.length; i++) {
                var lookingat = config[i];

                //if the config item has a key - check if it matches the refdatatype we are interested in
                if (typeof (lookingat.key) != "undefined") {
                    if (lookingat.key == refDataType) {
                        configitem = config[i];
                        break;
                    }
                }
                else {
                    throw "Badly formed refdata config - the config item must contain a key property.";
                }
            }

            //found relevant config item - now parse it
            if (configitem != null) {
                //first get filepath - if any, and add backslash, if necessary
                if (typeof (configitem.filePath) != "undefined") {
                    if (configitem.filePath.charAt(configitem.filePath.length - 1) != '/')
                        filePath = configitem.filePath + '/';
                    else
                        filePath = configitem.filePath();
                }//if servicepath specified, jump out of function and call service to get the refdata
                else if (typeof (configitem.servicePath) != "undefined") {
                    //no implementation of 
                    return getRefDataFromService(configitem.servicePath, obArray);
                }
            }

        }

        getRefDatafromFile(filePath, obArray, dfd);

        return dfd.promise;
    }


    //Gets the ref data from the specified JSON file
    //If an observable array is passed then it will populate that, otherwise it will pass the values in the callback
    //
    //filePath - the path to the refdata JSON file
    //array - the knockout observable array that the refdata items will be copied into    
    //dfd - deferred object from getRefData
    function getRefDatafromFile(filePath, obArray, dfd) {
        require([filePath], function (refDataFile) {
            if (typeof refDataFile === 'undefined') {
                dfd.reject('ref data file not found for path:' & filePath);
            } else if (ko.isObservable(obArray)) {
                obArray(komapping.fromJS(refDataFile.values).slice(0));
                dfd.resolve();
            } else {
                //if no array is passed - assumed that call is part of a promise that will return the values when resolved i.e. for ref data providers
                dfd.resolve(refDataFile.values);
            }
            return refDataFile;
        })
    }

    function getRefDataFilePath(refDataType, appName) {
        return appName + "/refdata/" + refDataType; //Need to lookup the app name from the child app shell appModuleId
    }

    function getExistingRequireRefData(refDataType, appName) {
        var requirePath = getRefDataFilePath(refDataType, appName);
        if (require.defined(requirePath)) {
            return require(requirePath);
        } else {
            console.log('required ref data not found');
        }
    }

    //***** Unimplemented - with throw an exception
    //Gets the ref data from the specified service
    //
    //servicePath - the path to the refdata service
    //obArray - the knockout observable array that the refdata items will be copied into
    function getRefDataFromService(servicePath, obArray) {
        throw "datacontext.getRefDataFromService() not yet implemented.";
    }

    function periodLookup(period, collection) {
        var returnVal;
        $.grep(collection, function (item) {
            if (item.period == period) {
                returnVal = item;
            }
        });
        if (typeof returnVal === 'undefined') {
            console.log('period' + period + 'not found');
        }
        return returnVal;
    }

});


define('shared/services/validator',[], function () {

    var validator = {
        isEmpty: isEmpty,
        isBlank: isBlank,
        isValidDate: isValidDate,
        isValidInteger: isValidInteger,
        integerWithinRange: integerWithinRange,
        dateFormats : ["D/MM/YYYY", "DD/MM/YYYY"]
    };

    return validator;
    
    /**
    *   Returns true if string is:
    *       - undefined 
    *       - null
    *       - zero length
    *
    *   @method isEmpty
    *   @param {string} str The string to validate
    *   @return {boolean} 
    **/
    function isEmpty(str) {
        return (!str || 0 === str.length);
    }


    /**
    **   Returns true if string is:
    *       - undefined 
    *       - null
    *       - zero length
    *       - white space
    *
    *   @method isBlank
    *   @param {string} str The string to validate 
    *   @return {boolean} 
    **/
    function isBlank(str) {
        return (!str || /^\s*$/.test(str));
    }

    /**
    **   Returns true if string is:
    *       - undefined 
    *       - null
    *       - zero length
    *       - white space
    *
    *   @method isBlank
    *   @param {string} str The string to validate 
    *   @return {boolean} 
    **/
    function isValidDate(str) {
        if (str) {
            return moment(str, dateFormats, true).isValid();
        } else {
            return false;
        }
    }

    //isValidInteger:
    //str - string of number
    //signed - boolean to test if it should be signed
    function isValidInteger(str, signed) {
        if (str) {
            var returnVal;
            var intRegex;
            if (typeof signed === 'undefined' || signed == true) {
                intRegex = /^\d+$/;
            } else {
                intRegEx = /-?\d+/;
            }
            return intRegex.test(str);
        } else {
            return false;
        }
    };

    //isValidInteger:
    //str - string of number
    //start - string of start number
    //end - string of end number
    //startInclude - boolean 
    //endInclude - boolean
    function integerWithinRange(str, start, end, startInclude, endInclude) {
        var returnVal;
        if (typeof startInclude === 'undefined') {
            startInclude = true;
        }
        if (typeof endInclude === 'undefined') {
            endInclude = true;
        }

        if (isValidInteger(str) && isValidInteger(start) && isValidInteger(end)) {
            str = str == '' ? new BigNumber(0) : new BigNumber(str);
            start = start == '' ? new BigNumber(0) : new BigNumber(start);
            end = end == '' ? new BigNumber(0) : new BigNumber(end);

            if (startInclude && endInclude) {
                if (str.greaterThanOrEqualTo(start) && str.lessThanOrEqualTo(end)) {
                    returnVal = true;
                } else {
                    returnVal = false;
                }
            }
            if (!startInclude && endInclude) {
                if (str.greaterThan(start) && str.lessThanOrEqualTo(end)) {
                    returnVal = true;
                } else {
                    returnVal = false;
                }
            }
            if (startInclude && !endInclude) {
                if (str.greaterThanOrEqualTo(start) && str.lessThan(end)) {
                    returnVal = true;
                } else {
                    returnVal = false;
                }
            }
            return returnVal;
        };
    }

    function compareDate(date1, comparison, date2) {
        if (comparsion == '==') {
        } else if (comparsion == '<') {
        } else if (comparison == '<=') {
        } else if (comparison == '>') {
        } else if (comparison == '>=') {
        };
    };




});
